Let $N,m,d, h$ be natural numbers, with $d\geqslant h\geqslant m+2$, and let $c,C,\varepsilon$ be positive constants. Let $\Xi = \Xi(N):\mathbb{R}^h\longrightarrow \mathbb{R}^d$ be an injective linear map with integer coefficients, and assume that $\Xi(\mathbb{Z}^{h}) = \mathbb{Z}^d \cap \operatorname{im} \Xi$. Let $L = L(N):\mathbb{R}^h \longrightarrow \mathbb{R}^m$ be a surjective linear map. Assume that $\Vert \Xi \Vert_\infty \leqslant C$, $\Vert L \Vert_\infty \leqslant C$, $\operatorname{dist}(L,V_{\operatorname{rank}}(m,d)) \geqslant c$ and $\operatorname{dist}((\Xi,L),V_{\operatorname{degen},2}^*(m,d,h))\geqslant c$. Then there exists a natural number $s$ at most $d-2$, independent of $\varepsilon$, such that the following holds. Let $\sigma_F,\sigma_G$ be any two parameters in the range $0<\sigma_F,\sigma_G < 1/2$. Let $F:\mathbb{R}^h\longrightarrow [0,1]$ be a Lipschitz function supported on $[-N,N]^h$ with Lipschitz constant $O(1/\sigma_FN)$, and let $G:\mathbb{R}^{m}\longrightarrow [0,1]$ be a Lipschitz function supported on $[-\varepsilon,\varepsilon]^m$ with Lipschitz constant $O(1/\sigma_G)$. Let $\widetilde{\mathbf{r}}$ be a fixed vector in $\mathbb{Z}^d$, satisfying $\Vert \widetilde{\mathbf{r}}\Vert_\infty = O_{c,C,\varepsilon}(1)$. Suppose that $f_1,\dots,f_d:[N]\longrightarrow [-1,1]$ are arbitrary bounded functions satisfying  \[\min_j \Vert f_j\Vert_{U^{s+1}[N]} \leqslant \rho,\] for some $\rho$ in the range $0<\rho \leqslant 1$. Then
\begin{equation}

 T^{L,\Xi,\widetilde{\mathbf{r}}}_{F,G,N}(f_1,\dots,f_{d})\ll_{c,C,\varepsilon}  \rho^{\Omega(1)} (\sigma_F^{-O(1)} + \sigma_G^{-O(1)}) + \sigma_F^{-O(1)}N^{-\Omega(1)}. 
\end{equation}

Let $\sigma_F$ be a parameter in the range $0<\sigma_F < 1/2$. Assume the hypotheses of Theorem 2.12, with the exception that $F:\mathbb{R}^d \longrightarrow [0,1]$ now denotes a Lipschitz function supported on $[-2N,2N]^d$ and with Lipschitz constant $O(1/\sigma_FN)$. Let $u$ be the rational dimension of $L$, and assume that $u\leqslant m-1$. Then there exists a surjective linear map $L^\prime:\mathbb{R}^{d-u} \longrightarrow \mathbb{R}^{m-u}$, an injective linear map $\Xi:\mathbb{R}^{d-u} \longrightarrow \mathbb{R}^d$, a finite subset $\widetilde{R}\subset \mathbb{Z}^d$, and, for each $\widetilde{\mathbf{r}} \in \widetilde{R}$, functions $F_{\widetilde{\mathbf{r}}}:\mathbb{R}^{d-u} \longrightarrow \mathbb [0,1]$ and $G_{\widetilde{\mathbf{r}}}:\mathbb{R}^{m-u} \longrightarrow [0,1]$, that together satisfy the following properties:
\begin{enumerate}[(1)]
\item $\Xi$ has integer coefficients, $\Vert \Xi \Vert_\infty  = O_{c,C}(1)$, and $\Xi(\mathbb{Z}^{d-u}) = \mathbb{Z}^d \cap \operatorname{im} \Xi$;
\item $\vert \widetilde{R}\vert = O_{c,C}(1)$, and $\Vert \widetilde{\mathbf{r}}\Vert_\infty = O_{c,C}(1)$ for all $\widetilde{\mathbf{r}} \in \widetilde{R}$;
\item $F_{\widetilde{\mathbf{r}}}$ is supported on $[-O_{c,C}(N),O_{c,C}(N)]^{d-u}$, with Lipschitz constant $O_{c,C}(1/\sigma_FN)$, and $G_{\widetilde{\mathbf{r}}}$ is the indicator function of a convex domain contained in \\$[-O_{c,C,\varepsilon}(1),O_{c,C,\varepsilon}(1)]^{m-u}$;
\item $T_{F,G,N}^L(f_1,\dots,f_d) = \sum\limits_{\widetilde{\mathbf{r}} \in \widetilde{R}}T_{F_{\widetilde{\mathbf{r}}},G_{\widetilde{\mathbf{r}}},N}^{L^\prime,\Xi,\widetilde{\mathbf{r}}}(f_1,\dots,f_d);$
\item $L^\prime$ is purely irrational;
\item $\Vert L^\prime\Vert_\infty = O_{c,C}(1)$ and $\operatorname{dist}(L^\prime, V_{\operatorname{rank}}(m-u,d-u)) = \Omega_{c,C}(1)$;
\item $\operatorname{dist}((\Xi,L^\prime),V_{\operatorname{degen},2}^*(m-u,d,d-u)) = \Omega_{c,C}(1)$;
\item for all $\tau_1,\tau_2 \in (0,1]$, $A_{L^\prime}(\tau_1,\tau_2) \gg_{c,C} A_L(\Omega_{c,C}(\tau_1),\Omega_{c,C}(\tau_2))$;
\item for all $\tau_1,\tau_2 \in (0,1]$, $A_{L^\prime}(\tau_1,\tau_2) \ll_{c,C} A_L(\Omega_{c,C}(\tau_1),\Omega_{c,C}(\tau_2))$.
\end{enumerate}

Let $m,d,h$ be natural numbers, satisfying $d\geqslant h\geqslant m+1$. Let $c,C,\varepsilon$ be positive, and let $\sigma_G$ be any parameter in the range $0<\sigma_G<1/2$. Let $L^\prime:\mathbb{R}^h \longrightarrow \mathbb{R}^m$ be a purely irrational surjective map, and let $\Xi:\mathbb{R}^{h} \longrightarrow \mathbb{R}^d$ be an injective map. Suppose that $\Vert L^\prime\Vert_\infty \leqslant C$ and that $\operatorname{dist}(L^\prime, V_{\operatorname{rank}}(m,h)) \geqslant c$. Let $F_{\widetilde{\mathbf{r}}}:\mathbb{R}^h \longrightarrow [0,1]$ be any function supported on $[-N,N]^h$, and let $G_{\widetilde{\mathbf{r}}}:\mathbb{R}^m \longrightarrow [0,1]$ be the indicator function of a convex set contained within $[-\varepsilon,\varepsilon]^m$. Then there exists a Lipschitz function $G_{\widetilde{\mathbf{r}}, \sigma_G,1}$ supported on $[-O_{c,C,\varepsilon}(1),O_{c,C,\varepsilon}(1)]^{m}$, and with Lipschitz constant $O_{c,C,\varepsilon}(1/\sigma _G)$, such that, for any parameter $\tau_2$ in the range $0<\tau_2\leqslant 1$ and for any functions $f_1,\dots,f_d:[N] \longrightarrow [-1,1]$,
\begin{align*}
\vert &T_{F_{\widetilde{\mathbf{r}}},G_{\widetilde{\mathbf{r}}},N}^{L^\prime,\Xi,\widetilde{\mathbf{r}}}(f_1,\dots,f_d)\vert \\ &\ll_{c,C,\varepsilon} \vert T_{F_{\widetilde{\mathbf{r}}},G_{\widetilde{\mathbf{r}},\sigma_G,1},N}^{L^\prime,\Xi,\widetilde{\mathbf{r}}}(f_1,\dots,f_d)\vert + \sigma_G + \frac{\tau_2^{1/2}}{\sigma _G} +  \frac{\tau_2^{-O(1)}A_L(\Omega_{c,C}(1),\tau_2)^{-1}}{N}.
\end{align*}

Let $N,m,d$ be natural numbers, with $d\geqslant m+1$. Let $c,C,\varepsilon$ be positive constants, and let $\sigma_G$ be a parameter in the range $0<\sigma_G < 1/2$. Suppose that $L:\mathbb{R}^d \longrightarrow \mathbb{R}^m$ is a purely irrational surjective linear map, satisfying $\Vert L\Vert_\infty \leqslant C$ and $\operatorname{dist}(L,V_{\operatorname{rank}}(m,d)) \geqslant c$. Let $A_L$ denote the approximation function of $L$. Let $F:\mathbb{R}^d \longrightarrow [0,1]$ be supported on $[-N,N]^d$, and let $G:\mathbb{R}^m\longrightarrow [0,1]$ be a Lipschitz function, with Lipschitz constant $O(1/\sigma_G)$, supported on $[-\varepsilon,\varepsilon]^m$. Assume further that $\int_{\mathbf{x}} G(\mathbf{x}) \, d\mathbf{x} = O_\varepsilon(\sigma_G)$. Then for all $\tau_2$ in the range $0<\tau_2\leqslant 1$, 
\begin{equation*}
 T_{F,G,N}^L(1,\dots,1) \ll_{c,C,\varepsilon} \sigma_G + \frac{\tau_2^{1/2}}{\sigma _G} +  \frac{\tau_2^{-O(1)}A_L(\Omega_{c,C}(1),\tau_2)^{-1}}{N}.
 \end{equation*}

Let $m,d$ be natural numbers, with $d\geqslant m+1$. Let $c,C$ be positive constants. Then there are positive constants $D_{c,C}, D^\prime_{c,C}$ for which the following holds. Let $L:\mathbb{R}^d\longrightarrow \mathbb{R}^m$ be a surjective linear map, denoted by matrix $(\lambda_{ij})_{i\leqslant m,j\leqslant d}$, and assume that $\Vert L\Vert_\infty \leqslant C$ and $\operatorname{dist}(L,V_{\operatorname{rank}}(m,d)) \geqslant c$. Then there exists a matrix $M$ that is an $m$-by-$m$ submatrix of $L$ and enjoys the following properties:
\begin{enumerate}[(1)]
\item  $\vert\operatorname{det}M\vert \geqslant D_{c,C}$; \\
\item $\Vert M^{-1}\Vert_{\infty} \leqslant D^\prime_{c,C}$.\\
\end{enumerate}
\noindent We call such a matrix $M$ a \emph{rank matrix} of $L$. Furthermore,\\
\begin{enumerate}[(1)]
\setcounter{enumi}{2}
\item Let $\mathbf{v}\in \mathbb{R}^d$ be a vector such that $\mathbf{v}^T$ is in the row-space of $L$, and suppose that $\Vert \mathbf{v}\Vert_\infty \leqslant C_1$ for some positive constant $C_1$. Then for all $i$ in the range $1\leqslant i\leqslant m$ there exist coefficients $a_i$ satisfying $\vert a_i\vert = O_{c,C,C_1}(1)$ such that $\sum\limits_{i=1}^m a_i \lambda_{ij} = v_{j}$ for all $j$ in the range $1\leqslant j\leqslant d$. \\
\end{enumerate}
Finally,\\
\begin{enumerate}
\setcounter{enumi}{3}
\item If $L$ satisfies the stronger hypothesis $\operatorname{dist}(L,V_{\operatorname{rank}}^{\operatorname{unif}}(m,d))\geqslant c$, then, for each $j$, there exists a rank matrix of $L$ that doesn't include the $j^{th}$ column of $L$.
\end{enumerate}

Let $u,d,$ be integers with $d\geqslant u+1$, and let $C,\eta$ be constants. Let $S:\mathbb{R}^d \longrightarrow \mathbb{R}^u$ be a surjective linear map with $S(\mathbb{Z}^d) \subseteq \mathbb{Z}^u$, and suppose that $\Vert S\Vert_\infty \leqslant C$. Let $\{\mathbf{a_1},\dots,\mathbf{a_u}\}$ be a basis for the lattice $S(\mathbb{Z}^d)$ that satisfies $\Vert \mathbf{a_i}\Vert_\infty = O_{C}(1)$ for every $i$. Let $\mathbf{x_1},\dots,\mathbf{x_u}\in\mathbb{Z}^d$ be vectors such that, for every $i$, $S(\mathbf{x_i}) = \mathbf{a_i}$ and $\Vert \mathbf{x_i}\Vert_\infty = O_{C}(1)$. Suppose that $\Xi:\mathbb{R}^{d-u}\longrightarrow \mathbb{R}^d$ is an injective linear map such that $\operatorname{im} \Xi = \ker S$ and such that $\Xi(\mathbb{Z}^{d-u}) = \mathbb{Z}^d \cap\operatorname{im} \Xi$. Suppose further that $\Vert \Xi\Vert_\infty \leqslant C$. 

Let $\mathbf{w_1},\dots,\mathbf{w_{d-u}}$ denote the standard basis vectors in $\mathbb{R}^{d-u}$. Then 
\begin{enumerate}[(1)]
\item the set $\mathcal{B}: = \{ \mathbf{x_i}: i\leqslant u\} \cup \{\Xi(\mathbf{w_j}): j\leqslant d-u\}$ is a basis for $\mathbb{R}^d$, and a lattice basis for $\mathbb{Z}^d$;
\item writing $\mathcal{B}^* := \{ \mathbf{x_i^*}: i\leqslant u\} \cup \{\Xi(\mathbf{w_j})^*: j\leqslant d-u\}$ for the dual basis, both the change of basis matrix between the standard dual basis and $\mathcal{B}^*$ and the inverse of this matrix have integer coordinates. The coefficients of both of these matrices are bounded in absolute value by $O_{C}(1)$.
\end{enumerate}

\noindent  Write $V: = \operatorname{span}(\mathbf{x_i^*}: i\leqslant u)$ and $W: = \operatorname{span}(\Xi(\mathbf{w_j})^*: j\leqslant d-u)$. Then

\begin{enumerate}[(1)]
\setcounter{enumi}{2}
\item $V = S^*((\mathbb{R}^u)^*)$;
\item Suppose that $\varphi \in (\mathbb{R}^d)^*$ satisfies $\Vert \Xi^*(\varphi)\Vert_\infty \leqslant \eta$. Then, writing $\varphi = \varphi_V + \varphi_W$ with $\varphi_V \in V$ and $\varphi_W \in W$, we have $\Vert \varphi_W\Vert_\infty = O_C(\eta)$. 
\end{enumerate}

Let $N,m,d, h$ be natural numbers, with $d\geqslant h\geqslant m+2$, and let $c,C,\varepsilon,\eta$ be positive constants. Let $\Xi:\mathbb{R}^h\longrightarrow \mathbb{R}^d$ be an injective linear map with integer coefficients, and assume that $\Xi(\mathbb{Z}^{h}) = \mathbb{Z}^d \cap \operatorname{im} \Xi$. Let $L:\mathbb{R}^h \longrightarrow \mathbb{R}^m$ be a surjective linear map. Assume that $\Vert \Xi \Vert_\infty \leqslant C$, $\Vert L \Vert_\infty \leqslant C$, and $\operatorname{dist}(L,V_{\operatorname{rank}}(m,h)) \geqslant c$. Let $F:\mathbb{R}^h\longrightarrow [0,1]$ be a Lipschitz function supported on $[-N,N]^h$ with Lipschitz constant $O(1/\sigma_FN)$, and let $G:\mathbb{R}^{m}\longrightarrow [0,1]$ be a Lipschitz function supported on $[-\varepsilon,\varepsilon]^m$ with Lipschitz constant $O(1/\sigma_G)$. Let $\widetilde{\mathbf{r}}$ be a fixed vector in $\mathbb{Z}^d$, satisfying $\Vert \widetilde{\mathbf{r}}\Vert_\infty = O_{c,C,\varepsilon}(1)$. Let $\chi:\mathbb{R}\longrightarrow [0,1]$ be an $\eta$-supported measurable function. Then, if $\eta$ is small enough (in terms of the dimensions $m,d,h$, $C$, and $\varepsilon$) there exists some positive real number $C_{\Xi,\chi}$ such that, if $f_1,\dots,f_d:[N]\longrightarrow [-1,1]$ are arbitrary functions,
\begin{equation}

T_{F,G,N}^{\Xi,L,\widetilde{\mathbf{r}}}(f_1,\dots,f_d) = \frac{1}{C_{\Xi,\chi}\eta^{h}}\widetilde{T}_{F,G,N}^{\Xi,L,\widetilde{\mathbf{r}}}(f_1\ast \chi,\dots,f_d\ast \chi) + O_{C,c,\varepsilon}(\eta/\sigma_G) + O_{C,c,\varepsilon}(\eta/\sigma_F N).
\end{equation}
\noindent Moreover, $C_{\Xi,\chi} \asymp_C 1$.

Let $s$ be a natural number, and assume that $\eta$ is a positive parameter that is small enough in terms of $s$. Let $\chi:\mathbb{R}\longrightarrow [0,1]$ be an $\eta$-supported measurable function. Let $N$ be a natural number, and let $f:[N]\longrightarrow \mathbb{R}$ be an arbtirary function. View $f\ast \chi$ as a function supported on $[-2N,2N]$. Then we have \begin{equation}

\Vert f\ast \chi\Vert_{U^{s+1}(\mathbb{R},2N)}\ll \eta^{\frac{s+2}{2^{s+1}}} \Vert f\Vert_{U^{s+1}[N]}. 
\end{equation}

Let $N,m,d,h$ be natural numbers, with $d\geqslant h\geqslant m+2$, and let $c,C,\varepsilon$ be positive reals. Let $\Xi = \Xi(N):\mathbb{R}^{h}\longrightarrow \mathbb{R}^d$ be an injective linear map with integer coefficients, and let $L = L(N):\mathbb{R}^d \longrightarrow\mathbb{R}^m$ be a surjective linear map. Suppose further that $\Vert L\Vert_\infty \leqslant C$, $\Vert \Xi\Vert_\infty \leqslant C$, $\operatorname{dist}( L,V_{\operatorname{rank}}(m,d)) \geqslant c$ and $\operatorname{dist} ((\Xi,L), V_{\operatorname{degen},2}^*(m,d,h))\geqslant c$. Then there is some natural number $s$ at most $d-2$, independent of $\varepsilon$, such that the following holds. Let $\widetilde{\mathbf{r}} \in \mathbb{Z}^d$ be some vector with $\Vert \widetilde{\mathbf{r}}\Vert_\infty = O_{c,C,\varepsilon}(1)$, and let $\sigma_F$ be a parameter in the range $O < \sigma_F < 1/2$. Let $F:\mathbb{R}^h\longrightarrow [0,1]$ be a Lipschitz function supported on $[-N,N]^h$, with Lipschitz constant $O(1/\sigma_FN)$, and let $G:\mathbb{R}^{m} \longrightarrow [0,1]$ be any function supported on $[-\varepsilon, \varepsilon]^m$.  Let $g_1,\dots,g_d:[-2N,2N]^d\longrightarrow [-1,1]$ be arbitrary measurable functions. Suppose \[ \min\limits_{j\leqslant d}\Vert g_j\Vert_{U^{s+1}(\mathbb{R},2N)}\leqslant \rho\] for some $\rho$ at most $1$. Then 
\begin{equation}
\vert \widetilde{T}_{F,G,N}^{L,\Xi,\widetilde{\mathbf{r}}}(g_1,\dots,g_d)\vert\ll_{c,C,\varepsilon} \rho^{\Omega(1)}\sigma_F^{-1} 
\end{equation}
\noindent

Let $s,d$ be natural numbers, with $d\geqslant 3$, and let $C$ be a positive constant. Let $\sigma_F$ be a parameter in the range $0 <\sigma_F<1/2$. Let $(\psi_1,\dots,\psi_d) = \Psi:\mathbb{R}^{s+1} \longrightarrow \mathbb{R}^d$ be a linear map, and suppose that $ \psi_1(\mathbf{e_k}) = 1$, for all the standard basis vectors $\mathbf{e_k} \in \mathbb{R}^{s+1}$. Suppose that, for all $j$ in the range $2\leqslant j\leqslant s+1$, there exists some $k$ such that $\psi_j(\mathbf{e_k}) = 0$. Let $N\geqslant 1$ be real, and let $g_1,\dots,g_d:[-N,N]\longrightarrow [-1,1]$ be arbitrary measurable functions, and, for each $j$ at most $d$, let $a_j$ be some real number with $\vert a_j\vert \leqslant CN$. Let $F:\mathbb{R}^{s+1} \longrightarrow [0,1]$ be any Lipschitz function, supported on $[-CN,CN]^{s+1}$ with Lipschitz constant $O(1/\sigma_F N)$. Suppose that $\Vert g_1 \Vert _{U^{s+1}(\mathbb{R},N)} \leqslant \rho$, for some parameter $\rho$ in the range $0<\rho\leqslant 1$. Then 
\begin{equation}

\Big\vert\frac{1}{N^{s+1}} \int\limits_{\mathbf{w}\in \mathbb{R}^{s+1}} \prod\limits_{j=1}^d g_j (\psi_j(\mathbf{w}) + a_j)  F(\mathbf{w})\, d\mathbf{w}\Big\vert \ll_C \rho^{-\Omega(1)} \sigma_F^{-1}.
\end{equation}

Let $N,m,d, h$ be natural numbers, with $d\geqslant h\geqslant m+2$, and let $c,C,\varepsilon$ be positive constants. Let $\sigma_F$ be a parameter in the range $0 <\sigma_F<1/2$. Let $\Xi:\mathbb{R}^h\rightarrow \mathbb{R}^d$ be an injective linear map with integer coefficients, and let $L:\mathbb{R}^h \longrightarrow \mathbb{R}^m$ be a surjective linear map. Assume further that $\Vert L \Vert_\infty \leqslant C$, $\Vert \Xi\Vert_\infty \leqslant C$, $\operatorname{dist}(L,V_{\operatorname{rank}}(m,h))\geqslant c$ and $\operatorname{dist} ((\Xi,L),V_{\operatorname{degen},2}^\ast (m,d,h)) \geqslant c$. Let $F:\mathbb{R}^h\longrightarrow [0,1]$ be a Lipschitz function supported on $[- CN,CN]^h$, with Lipschitz constant $O_C(1/\sigma_F N)$, and let $G:\mathbb{R}^{m}\longrightarrow [0,1]$ be a measurable function supported on $[-\varepsilon,\varepsilon]^m$. Let $\widetilde{\mathbf{r}}$ be a fixed vector in $\mathbb{Z}^d$, satisfying $\Vert \widetilde{\mathbf{r}}\Vert_\infty = O_{C}(1)$. Then there exists a system of linear forms $(\psi_1,\dots,\psi_d) = \Psi:\mathbb{R}^{h-m}\longrightarrow \mathbb{R}^d$ satisfying $\Vert \Psi\Vert_\infty = O_C(1)$, and a Lipschitz function $F_1:\mathbb{R}^{h-m}\longrightarrow [0,1]$ supported on $[-O_{c,C,\varepsilon}(N),O_{c,C,\varepsilon}(N)]^{h-m}$ with Lipschitz constant $O(1/\sigma_F N)$, such that, if $g_1,\dots,g_d:[-2N,2N]\longrightarrow [-1,1]$ are arbitrary functions, 
\begin{equation}
\vert\widetilde{T}_{F,G,N}^{L,\Xi,\widetilde{\mathbf{r}}}(g_1,\dots,g_d)\vert\ll_{c,C,\varepsilon} \Big\vert\frac{1}{N^{h-m}}\int\limits_{\mathbf{x}} \prod\limits_{j=1}^d g_j(\psi_j(\mathbf{x}) + a_j)F_1(\mathbf{x}) \, d\mathbf{x}\Big\vert ,
\end{equation}
\noindent where, for each $j$, $a_j$ is some real number that satisfies $a_j = O_{c,C,\varepsilon}(1)$.

Furthermore, there exists a natural number $s$ at most $d-2$ such that the system $\Psi$ has $\Omega_{c,C}(1)$-Cauchy-Schwarz complexity at most $s$, in the sense of Definition 4.6.

Let $m,n$ be natural numbers, with $m\geqslant 3$, and let $c_1,C_1$ be positive constants. Let $(\psi_1,\dots,\psi_m) = \Psi:\mathbb{R}^n \longrightarrow \mathbb{R}^m$ be a system of homogeneous linear forms, and suppose that the coefficients of $\Psi$ are bounded above in absolute value by $C_1$. Furthermore, suppose that $\Psi$ has $c_1$-Cauchy-Schwarz complexity $s$, for some finite $s$. Then, for each $i \in [m]$, there is an extension $\Psi^\prime:\mathbb{R}^{n^\prime}\longrightarrow \mathbb{R}^m$ such that:
\begin{enumerate}[(1)]
\item $n^\prime = n+s+1 \leqslant n+m-1$; 
\item $\Psi^\prime$ is of the form $$\Psi^\prime(\mathbf{u}, w_1,\dots,w_{s+1}): = \Psi(\mathbf{u} + w_1\mathbf{f_1}+ \cdots + w_{s+1}\mathbf{f_{s+1}})$$ for some vectors $\mathbf{f_k}\in \mathbb{R}^n$, such that $\Vert \mathbf{f_k}\Vert_\infty=O_{c_1,C_1}(1)$ for every $k$;
\item $\Psi^\prime$ is in normal form with respect to $\psi_i^\prime$;
\item $\psi_i^\prime(\mathbf{0},\mathbf{w}) = w_1 + \cdots + w_{s+1}$.
\end{enumerate}
